export const DICT: Record<Lang, Record<Key, string>> = { en, hi };
let lang: Lang = 'en';
export function setLang(l: Lang) { lang = l; document.documentElement.lang = l; }
export function getLang(): Lang { return lang; }
export function t(k: Key, vars?: Record<string, string | number>): string {
  let s = DICT[lang][k] ?? DICT.en[k] ?? k;
  if (vars) for (const [a, b] of Object.entries(vars)) s = s.replace(`{${a}}`, String(b));
  return s;
}
